def maximum_drawdown_percentage(prices: list[float]) -> float:
    p_list = [float(x) for x in prices]
    if not p_list:
        return 0.0
    peak = max(0.0001, p_list[0])
    max_dd = 0.0
    for p in p_list:
        val = max(0.0001, p)
        if val > peak:
            peak = val
        dd = (peak - val) / peak
        if dd > max_dd:
            max_dd = dd
    return max_dd

def markowitz_portfolio_variance(weights: list[float], cov_matrix: list[list[float]]) -> float:
    w = [float(x) for x in weights]
    n = len(w)
    if n == 0 or len(cov_matrix) < n:
        return 0.0
    total_var = 0.0
    for i in range(n):
        row = cov_matrix[i]
        if len(row) < n:
            continue
        for j in range(n):
            cov_ij = float(row[j])
            total_var = total_var + w[i] * w[j] * cov_ij
    return max(0.0, total_var)

def twap_time_weighted_price(prices: list[float], time_intervals: list[float]) -> float:
    p_arr = [float(x) for x in prices]
    dt_arr = [max(0.0, float(x)) for x in time_intervals]
    k = min(len(p_arr), len(dt_arr))
    if k == 0:
        return 0.0
    weighted_sum = 0.0
    cumulative_time = 0.0
    for idx in range(k):
        interval = dt_arr[idx]
        if interval > 0.0:
            weighted_sum = weighted_sum + p_arr[idx] * interval
            cumulative_time = cumulative_time + interval
    if cumulative_time <= 1e-12:
        return sum(p_arr[:k]) / float(k)
    twap_val = weighted_sum / cumulative_time
    return twap_val
